import{_ as t,o,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2017-MAY-11 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-MAY-11 :: Ceph Performance Weekly","date":"2017-05-17T00:00:00.000Z","updated":"2017-05-17T00:00:00.000Z","tags":["Ceph","性能优化","RBD","BlueStore","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAY-11_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-MAY-11_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),s={name:"posts/2017/2017-MAY-11_-_-_Ceph_Performance_Weekly.md"};function a(n,e,i,p,_,c){return o(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 会议主持人、Ceph社区成员、阿里巴巴工程师（Mark、Jesse、Gem、Cliff）等</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph社区近期工作</strong></p><ol><li><strong>Poll请求</strong>：讨论了多个优化请求，包括启用sink rights提高小IO性能、优化manager、scrubbing功能合并、cache miss rate优化、blue store compaction read ahead优化、新的编码和修复方案、blue FS sync right选项添加等。</li><li><strong>Purple请求</strong>：讨论了优化RBD性能和异步消息传递工作。</li></ol><p><strong>二、Ceph社区未来工作</strong></p><ol><li><strong>RBD性能优化</strong>：分析RBD client-side瓶颈，考虑禁用BD cache，评估RBD与文件系统的性能对比。</li><li><strong>BlueStore优化</strong>：blue store compaction read ahead优化、Kvsync线程拆分、3x replication与blue store erasure coding性能对比、partial reads优化等。</li><li><strong>其他工作</strong>：CRC计算优化、blue FS在共享设备中的放置、adaptive throttle工作、Kvsync线程拆分。</li></ol><p><strong>三、阿里巴巴工程师工作</strong></p><ol><li><strong>Commit majority功能</strong>：实现了commit majority功能，提高了平均延迟和延迟抖动，将在客户端和收集器端进一步实现。</li><li><strong>与Ceph社区的协作</strong>：邀请Ceph社区成员对commit majority功能进行审查，合作优化Ceph性能。</li></ol><p><strong>四、行动计划</strong></p><ol><li>Ceph社区成员将继续关注RBD性能优化、BlueStore优化等工作。</li><li>阿里巴巴工程师将与Ceph社区合作，优化Ceph性能。</li><li>Ceph社区成员将参与commit majority功能的审查工作。</li></ol><p><strong>五、其他</strong></p><ol><li>讨论了RBD与文件系统性能对比的问题。</li><li>讨论了BlueStore在共享设备中的放置问题。</li><li>讨论了adaptive throttle工作。</li></ol><p><strong>六、会议总结</strong></p><p>本次会议讨论了Ceph社区近期工作和未来工作计划，并邀请阿里巴巴工程师参与Ceph性能优化工作。会议气氛热烈，讨论深入。</p>',16)])])}const m=t(s,[["render",a]]);export{h as __pageData,m as default};
